  (* [comment removed for export] *)
  Lemma L_zfillr : forall (k : nat) Q m (x1 x5 x6 x7 x10 x12 x13 x14 x15 x16 x17 x18 x19 x20 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word) fc K
      (estrp ppl fl2 a8v v440 : Z) (oc : list Z) (ws : list word) (s : Z) (b b' : list Z),
    emw K estrp ppl fl2 a8v v440 oc m fc ->
    u32arr rsegs m (bv_unsigned sp + -1056) ws -> length ws = 128%nat ->
    length (K_jk37 K) = 37%nat -> (1 <= s <= 9)%Z -> (Z.to_nat s <= k)%nat ->
    length b = 37%nat -> length b' = 37%nat ->
    (forall i, (s <= i < 9)%Z -> nth_error (K_jk37 K) (Z.to_nat i) = Some (Z_to_bv 8 (znth b i))) ->
    (forall i, (0 <= i < s)%Z -> znth b' i = CHR_0) -> (forall i, (s <= i)%Z -> znth b' i = znth b i) ->
    (forall m1 bf1 (x11' : word),
       emw (K_set37 K bf1) estrp ppl fl2 a8v v440 oc m1 fc -> u32arr rsegs m1 (bv_unsigned sp + -1056) ws -> length bf1 = 37%nat ->
       (forall i, (0 <= i < 9)%Z -> nth_error bf1 (Z.to_nat i) = Some (Z_to_bv 8 (znth b' i))) ->
       evt rsegs Q
         (MS (mkR x1 SPv gp tp x5 x6 x7 sp (Z_to_bv 64 99) (Z_to_bv 64 (bv_unsigned sp + -405)) x11' x12 x13 x14 x15 x16 x17
                  x18 x19 x20 (Z_to_bv 64 (bv_unsigned sp + -405)) (Z_to_bv 64 48) x23 x24 x25 x26 x27 x28 x29 x30 x31)
             (K_Ft K) (Z_to_bv 64 0xb5efc) fc None m1 (seg_rom rsegs))) ->
    evt rsegs Q
      (MS (mkR x1 SPv gp tp x5 x6 x7 sp (Z_to_bv 64 99) x10 (Z_to_bv 64 (bv_unsigned sp + -405 + s)) x12 x13 x14 x15 x16 x17
